@Transactional(rollbackFor = Exception.class)
public void pay(String orderId, Money amount) {
    orderRepository.lockForUpdate(orderId);   // гонка списаний
    accountRepository.debit(amount);
    eventRepository.append(new OrderPaid(orderId));
} // commit или rollback — на выходе из метода
